const devices = global.get('devices') || {};
const configs = global.get('device_configs') || {};
const allDevs = Object.values(devices);

const msgs = [];

// Build index mapping
const acList = [];
const lightList = [];
const signList = [];

allDevs.forEach(d => {
    const cfg = configs[d.id];
    if (!cfg) return;
    if (cfg.type === 'ac_controller') acList.push(d);
    else if (cfg.type === 'mcb' || cfg.type === 'switch') lightList.push(d);
    else if (cfg.type === 'sign') signList.push(d);
});

// Publish AC status
acList.forEach((d, idx) => {
    const s = d.state || {};
    msgs.push({ topic: 'bms/ac/' + idx + '/temperature', payload: String(s.temperature || 0), qos: 0, retain: false });
    msgs.push({ topic: 'bms/ac/' + idx + '/room_temp', payload: String(s.ambient_temp || 0), qos: 0, retain: false });
    msgs.push({ topic: 'bms/ac/' + idx + '/power', payload: s.power ? 'ON' : 'OFF', qos: 0, retain: false });
    msgs.push({ topic: 'bms/ac/' + idx + '/mode', payload: String(s.mode || 0), qos: 0, retain: false });
    msgs.push({ topic: 'bms/ac/' + idx + '/online', payload: s.online ? 'ON' : 'OFF', qos: 0, retain: false });
});

// Publish Light status
lightList.forEach((d, idx) => {
    const s = d.state || {};
    msgs.push({ topic: 'bms/light/' + idx + '/power', payload: s.power ? 'ON' : 'OFF', qos: 0, retain: false });
    msgs.push({ topic: 'bms/light/' + idx + '/online', payload: s.online ? 'ON' : 'OFF', qos: 0, retain: false });
});

// Publish Sign status
signList.forEach((d, idx) => {
    const s = d.state || {};
    msgs.push({ topic: 'bms/sign/' + idx + '/power', payload: s.power ? 'ON' : 'OFF', qos: 0, retain: false });
    msgs.push({ topic: 'bms/sign/' + idx + '/online', payload: s.online ? 'ON' : 'OFF', qos: 0, retain: false });
});

// Summary
const acOn = acList.filter(d => d.state?.power).length;
const acAvg = acList.length > 0 ? Math.round(acList.reduce((sum, d) => sum + (d.state?.temperature || 0), 0) / acList.length) : 0;
const ltOn = lightList.filter(d => d.state?.power).length;

msgs.push({ topic: 'bms/status/ac_on_count', payload: String(acOn), qos: 0, retain: false });
msgs.push({ topic: 'bms/status/ac_avg_temp', payload: String(acAvg), qos: 0, retain: false });
msgs.push({ topic: 'bms/status/lt_on_count', payload: String(ltOn), qos: 0, retain: false });

return [msgs];

const topic = msg.topic;
const payload = msg.payload;
const parts = topic.split('/');

const configs = global.get('device_configs') || {};
const devices = global.get('devices') || {};

// Build index lists
const acIds = [];
const lightIds = [];
const signIds = [];

Object.keys(configs).forEach(id => {
    const c = configs[id];
    if (c.type === 'ac_controller') acIds.push(id);
    else if (c.type === 'mcb' || c.type === 'switch') lightIds.push(id);
    else if (c.type === 'sign') signIds.push(id);
});

let deviceId = null;
let action = null;
let extra = null;
let gateway = null;

// bms/ac/0/power/set
if (parts[1] === 'ac' && parts[3] === 'power' && parts[4] === 'set') {
    const idx = parseInt(parts[2]);
    deviceId = acIds[idx];
    action = payload === 'ON' ? 'POWER_ON' : 'POWER_OFF';
}
// bms/ac/0/temperature/set
else if (parts[1] === 'ac' && parts[3] === 'temperature' && parts[4] === 'set') {
    const idx = parseInt(parts[2]);
    deviceId = acIds[idx];
    action = 'AC_SET';
    extra = { temp: parseInt(payload) };
}
// bms/ac/0/mode/set
else if (parts[1] === 'ac' && parts[3] === 'mode' && parts[4] === 'set') {
    const idx = parseInt(parts[2]);
    deviceId = acIds[idx];
    action = 'AC_SET';
    extra = { mode: parseInt(payload) };
}
// bms/light/0/power/set
else if (parts[1] === 'light' && parts[3] === 'power' && parts[4] === 'set') {
    const idx = parseInt(parts[2]);
    deviceId = lightIds[idx];
    action = payload === 'ON' ? 'POWER_ON' : 'POWER_OFF';
}
// bms/sign/0/power/set
else if (parts[1] === 'sign' && parts[3] === 'power' && parts[4] === 'set') {
    const idx = parseInt(parts[2]);
    deviceId = signIds[idx];
    action = payload === 'ON' ? 'POWER_ON' : 'POWER_OFF';
}
// bms/scene/master
else if (parts[1] === 'scene' && parts[2] === 'master') {
    // Scene master - broadcast to all devices
    node.warn('Scene master: ' + payload);
    return null;
}

if (!deviceId) {
    node.warn('Unknown topic: ' + topic);
    return null;
}

const cfg = configs[deviceId];
if (!cfg) { node.warn('No config for ' + deviceId); return null; }

const ex = cfg.extra || {};
gateway = cfg.gateway || ex.gateway;

// Build ZbSend
const writes = {};
if (action === 'POWER_ON') {
    writes[ex.power_attr || '0110'] = 1;
} else if (action === 'POWER_OFF') {
    writes[ex.power_attr || '0110'] = 0;
} else if (action === 'AC_SET') {
    writes[ex.ac_power_attr || '0101'] = 1;
    if (extra && extra.temp !== undefined) writes[ex.ac_temp_attr || '0202'] = extra.temp;
    if (extra && extra.mode !== undefined) {
        const modeMap = ex.ac_mode_map || { off: 0, cool: 1, heat: 2, fan_only: 3, dry: 4 };
        writes[ex.ac_mode_attr || '0405'] = modeMap[extra.mode] !== undefined ? modeMap[extra.mode] : extra.mode;
    }
}

msg.topic = 'cmnd/' + gateway + '/ZbSend';
msg.payload = JSON.stringify({ Device: deviceId, Write: writes });
msg._hmi_cmd = { deviceId, action, extra };
return msg;
